shared_html.shared_css:
/* ============================================================
   Shared chrome — Atelier Mirza Reza
   Persian Safavid · bold variant
   ============================================================ */

.site-nav,
.site-footer {
  font-family: "Cormorant Garamond", "Times New Roman", serif;
  color: var(--text);
  background: var(--bg);
}

/* ---------- HEADER ---------- */

.site-nav {
  position: relative;
  border-bottom: 1px solid color-mix(in srgb, var(--ornament) 35%, transparent);
}

.site-nav__bar {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 3rem;
  max-width: 1280px;
  margin: 0 auto;
  padding: 1.75rem 2.5rem 1.25rem;
}

.site-nav__brand {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  text-decoration: none;
  color: var(--text);
  line-height: 1.05;
}

.site-nav__brand-kicker {
  font-size: 0.72rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--primary);
  margin-bottom: 0.45rem;
}

.site-nav__brand-mark {
  font-family: "Cinzel Decorative", "Cinzel", serif;
  font-weight: 900;
  font-size: 1.85rem;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--text-emphasis);
}

.site-nav__brand-sub {
  font-style: italic;
  font-size: 0.95rem;
  color: var(--accent);
  margin-top: 0.3rem;
  letter-spacing: 0.04em;
}

.site-nav__menu {
  justify-self: end;
}

.site-nav__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 0.25rem 2rem;
  counter-reset: navitem;
}

.site-nav__list li {
  counter-increment: navitem;
  position: relative;
}

.site-nav__list li + li::before {
  content: "◈";
  position: absolute;
  left: -1.15rem;
  top: 50%;
  transform: translateY(-50%);
  color: var(--ornament);
  font-size: 0.55rem;
  opacity: 0.7;
}

.site-nav__list a {
  font-family: "Cinzel Decorative", serif;
  font-weight: 700;
  font-size: 0.82rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--accent);
  padding: 0.4rem 0.1rem;
  border-bottom: 1px solid transparent;
  transition: color 200ms ease, border-color 200ms ease;
}

.site-nav__list a:hover,
.site-nav__list a:focus {
  color: var(--text-emphasis);
  border-bottom-color: var(--primary);
  outline: none;
}

/* Filet divider — gold arabesque rule */
.site-nav__filet,
.site-footer__filet {
  height: 14px;
  background-color: var(--ornament);
  -webkit-mask: repeating-linear-gradient(
      90deg,
      black 0 14px,
      transparent 14px 18px
    ),
    radial-gradient(circle at 50% 50%, black 2px, transparent 2.5px) 0 0/22px 14px;
  mask: repeating-linear-gradient(
      90deg,
      black 0 14px,
      transparent 14px 18px
    ),
    radial-gradient(circle at 50% 50%, black 2px, transparent 2.5px) 0 0/22px 14px;
  opacity: 0.85;
}

.site-nav__filet {
  background:
    linear-gradient(90deg, transparent 0, var(--primary) 12%, var(--primary) 88%, transparent 100%);
  height: 2px;
  -webkit-mask: none;
  mask: none;
  opacity: 1;
  position: relative;
}

.site-nav__filet::before,
.site-nav__filet::after {
  content: "";
  position: absolute;
  top: -4px;
  width: 10px;
  height: 10px;
  background: var(--primary);
  transform: rotate(45deg);
}
.site-nav__filet::before { left: 8%; }
.site-nav__filet::after  { right: 8%; }

/* ---------- FOOTER ---------- */

.site-footer {
  margin-top: 6rem;
  padding-bottom: 2.5rem;
  background: var(--surface);
  position: relative;
  text-align: center;
}

.site-footer__filet {
  background: linear-gradient(
    90deg,
    transparent 0,
    var(--primary) 12%,
    var(--primary) 88%,
    transparent 100%
  );
  height: 2px;
  margin-bottom: 0;
  position: relative;
}

.site-footer__filet::before,
.site-footer__filet::after {
  content: "";
  position: absolute;
  top: -4px;
  width: 10px;
  height: 10px;
  background: var(--primary);
  transform: rotate(45deg);
}
.site-footer__filet::before { left: 8%; }
.site-footer__filet::after  { right: 8%; }

.site-footer__seal {
  display: flex;
  justify-content: center;
  margin: 2.25rem auto 1.5rem;
  color: var(--ornament);
  /* seal-breathe animation */
  animation: seal-breathe 3s ease-in-out infinite;
  transform-origin: center center;
}

@keyframes seal-breathe {
  0%, 100% { transform: scale(1); opacity: 0.92; }
  50%      { transform: scale(1.18); opacity: 1; }
}

.site-footer__grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 2.5rem;
  max-width: 1180px;
  margin: 1rem auto 2.5rem;
  padding: 0 2.5rem;
  text-align: left;
}

.site-footer__col h4 {
  font-family: "Cinzel Decorative", serif;
  font-weight: 700;
  font-size: 0.78rem;
  letter-spacing: 0.28em;
  text-transform: uppercase;
  color: var(--text-emphasis);
  margin: 0 0 0.9rem;
  padding-bottom: 0.5rem;
  border-bottom: 1px solid color-mix(in srgb, var(--ornament) 40%, transparent);
}

.site-footer__col p {
  margin: 0;
  font-size: 1.02rem;
  line-height: 1.7;
  color: var(--accent);
}

.site-footer__nav {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 0.35rem;
}

.site-footer__nav a {
  color: var(--accent);
  text-decoration: none;
  font-size: 1rem;
  letter-spacing: 0.04em;
  border-bottom: 1px solid transparent;
  transition: color 180ms ease, border-color 180ms ease;
}

.site-footer__nav a:hover,
.site-footer__nav a:focus {
  color: var(--text-emphasis);
  border-bottom-color: var(--primary);
  outline: none;
}

.site-footer__colophon {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 1.25rem;
  flex-wrap: wrap;
  font-size: 0.86rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: color-mix(in srgb, var(--accent) 75%, transparent);
  padding-top: 1.5rem;
  border-top: 1px solid color-mix(in srgb, var(--ornament) 25%, transparent);
  margin: 0 2.5rem;
}

.site-footer__diamond {
  color: var(--primary);
  font-size: 0.7rem;
}

/* ---------- responsive ---------- */

@media (max-width: 880px) {
  .site-nav__bar {
    grid-template-columns: 1fr;
    gap: 1.25rem;
    padding: 1.25rem 1.5rem 1rem;
    text-align: center;
  }
  .site-nav__brand { align-items: center; }
  .site-nav__menu { justify-self: center; }
  .site-nav__list { justify-content: center; gap: 0.4rem 1.5rem; }

  .site-footer__grid {
    grid-template-columns: 1fr 1fr;
    padding: 0 1.5rem;
    gap: 2rem;
  }
}

@media (max-width: 520px) {
  .site-nav__brand-mark { font-size: 1.4rem; }
  .site-nav__list a { font-size: 0.74rem; letter-spacing: 0.18em; }
  .site-footer__grid { grid-template-columns: 1fr; }
  .site-footer__colophon { font-size: 0.74rem; gap: 0.6rem; }
}
